        sendHULLO(*session);
        if (!waitFor([&] { return session->engine.acceptedFd.load() >= 0; }, 5000))
            return fail(name, "engine accept did not complete");
        usleep(100 * 1000);
        const int clientFd = session->clientFd;
        const int pipeFd = session->controller->closeNotificationPipeForForwardingThread[1];
        [session->controller simulateByePipeClose];
        if (!waitFor([&] { return fdClosed(clientFd); }, 5000))
            return fail(name, "forwarder did not close the client socket");
        if (!waitFor([&] { return fdClosed(pipeFd); }, 5000))
            return fail(name, "forwarder did not close the pipe end");
        session->controller = nil;
        if (!waitFor([&] { return session->weakController == nil; }, 5000))
            return fail(name, "forwarder leaked after the close notification");
        if (floeHarnessErrorLogCount() != 0)
            return fail(name, "close notification must not log errors");
        session->engine.stage.store(1);
        session->engine.join();
        resultLine(name, "verdict", "pass");
        return 0;
    }
}

static int scenario_duplicate_hullo_single_delivery(const char *name)
{
    @autoreleasepool {
        floeGateReset();
        sinkReset();
        floeHarnessResetErrorLog();
        auto session = startSession(true);
        session->engine.run([](Engine &engine) {
            engineAcceptHandshake(engine);
            fakeSocketWrite(engine.acceptedFd.load(), "only tile", 9);
            while (engine.stage.load() == 0)
                usleep(1000);
            fakeSocketClose(engine.acceptedFd.load());
        });
        sendHULLO(*session);
        sendHULLO(*session); // duplicate; no race gates involved
        if (!waitFor([&] { return sinkSnapshot().size() == 1; }, 5000))
            return fail(name, "record was not delivered");
        usleep(200 * 1000);
        if (sinkSnapshot().size() != 1 || sinkSnapshot()[0] != "only tile")
            return fail(name, "record delivered more than once");
        session->engine.stage.store(1);
        session->engine.join();
        session->controller = nil;
        if (!waitFor([&] { return session->weakController == nil; }, 5000))
            return fail(name, "forwarder leaked after EOF");
        if (floeHarnessErrorLogCount() < 1)
            return fail(name, "duplicate HULLO must be logged");
        resultLine(name, "verdict", "pass");
        return 0;
    }
}

static int scenario_connect_failure(const char *name)
{
    @autoreleasepool {
        floeGateReset();
        sinkReset();
        floeHarnessResetErrorLog();
        auto session = startSession(false); // valid server fd, never listening
        sendHULLO(*session);
        usleep(200 * 1000);
#if defined(FLOE_VARIANT_ORIGINAL)
        // NDEBUG: the failed connect is ignored, a forwarder starts on the
        // unconnected socket and blocks in poll until the close pipe fires.
        [session->controller simulateByePipeClose];
        session->controller = nil;
        if (!waitFor([&] { return session->weakController == nil; }, 5000))
            return fail(name, "original forwarder did not retire on pipe close");
        resultLine(name, "verdict", "pass");
        resultLine(name, "behavior", "forwarder blocked on unconnected socket until pipe close");
#else
        if (floeHarnessErrorLogCount() < 1)
            return fail(name, "patched must log the failed connect");
        if (floeGatePollCount() != 0)
            return fail(name, "patched must not start a forwarder on a dead socket");
        if ([session->controller forwarderActiveSnapshot])
            return fail(name, "failed connect must clear the ownership flag for a later retry");
        session->controller = nil;
        if (!waitFor([&] { return session->weakController == nil; }, 5000))
            return fail(name, "patched retained a forwarder on a dead socket");
        resultLine(name, "verdict", "pass");
        resultLine(name, "behavior", "no forwarder on failed connect");
        // The ownership flag is not latched: once the server listens, a
        // later HULLO connects and forwards normally.
        FloeFixtureDocument *document = [FloeFixtureDocument new];
        document->fakeClientFd = session->clientFd; // same client socket, never connected
        document->appDocId = 1;
        document->readOnly = NO;
        document->copyFileURL = [NSURL fileURLWithPath:@"/tmp/floe-harness/ppt/regression.pptx"];
        FloeFixtureController *controller = [FloeFixtureController new];
        controller.document = document;
        __weak FloeFixtureController *weakRetry = controller;
        Engine engine;
        engine.startListen();
        engine.run([](Engine &eng) {
            engineAcceptHandshake(eng);
            fakeSocketWrite(eng.acceptedFd.load(), "retry tile", 10);
            fakeSocketClose(eng.acceptedFd.load());
        });
        FloeFakeMessage *message = [FloeFakeMessage new];
        message.body = @"HULLO";
        [controller didReceiveHULLO:message];
        if (!waitFor([&] { return sinkSnapshot().size() == 1; }, 5000))
            return fail(name, "retry HULLO did not deliver");
        if (sinkSnapshot()[0] != "retry tile")
            return fail(name, "retry payload mismatch");
        engine.join();
        controller = nil;
        if (!waitFor([&] { return weakRetry == nil; }, 5000))
            return fail(name, "retry forwarder leaked");
        resultLine(name, "retry", "later HULLO after a failed connect delivers and retires cleanly");
#endif
        return 0;
    }
}

static int scenario_invalid_client_fd(const char *name)
{
    @autoreleasepool {
        floeGateReset();
        sinkReset();
        floeHarnessResetErrorLog();
        auto session = startSession(true);
        session->engine.run([](Engine &engine) {
            engineAcceptHandshake(engine);
            while (engine.stage.load() == 0)
                usleep(1000);
            fakeSocketClose(engine.acceptedFd.load());
        });
        sendHULLO(*session);
        if (!waitFor([&] { return session->engine.acceptedFd.load() >= 0; }, 5000))
            return fail(name, "engine accept did not complete");
        fakeSocketClose(session->clientFd); // defensive: fd gone under the forwarder
        usleep(200 * 1000);
#if defined(FLOE_VARIANT_ORIGINAL)
        // POLLNVAL fails both equality checks: the original spins until the
        // pipe close retires it.
        if (floeGatePollCount() < 5)
            return fail(name, "original must spin on POLLNVAL");
        [session->controller simulateByePipeClose];
        session->controller = nil;
        if (!waitFor([&] { return session->weakController == nil; }, 5000))
            return fail(name, "original forwarder did not retire on pipe close");
        resultLine(name, "verdict", "pass");
        resultLine(name, "behavior", "spun on POLLNVAL; retired only via pipe close");
#else
        const int pipeFd = session->controller->closeNotificationPipeForForwardingThread[1];
        session->controller = nil;
        if (!waitFor([&] { return session->weakController == nil; }, 5000))
            return fail(name, "patched forwarder leaked after POLLNVAL");
        if (floeHarnessErrorLogCount() < 1)
            return fail(name, "patched must log the invalid socket");
        if (!fdClosed(pipeFd))
            return fail(name, "patched POLLNVAL retirement must close the pipe end");
        resultLine(name, "verdict", "pass");
        resultLine(name, "behavior", "clean retire on POLLNVAL");
#endif
        session->engine.stage.store(1);
        session->engine.join();
        return 0;
    }
}

// ---------------------------------------------------------------------------

static void installTerminateMarker()
{
    std::set_terminate([] {
        const char *type = "unknown";
        try {
            if (std::exception_ptr current = std::current_exception())
                std::rethrow_exception(current);
        } catch (const std::length_error &) {
            type = "std::length_error";
        } catch (const std::exception &) {
            type = "std::exception";
        } catch (...) {
        }
        fprintf(stderr, "FLOE_TERMINATE type=%s\n", type);
        fflush(stderr);
        abort();
    });
}

int main(int argc, char **argv)
{
    std::string scenario;
    for (int i = 1; i < argc; i++) {
        if (std::strcmp(argv[i], "--scenario") == 0 && i + 1 < argc)
            scenario = argv[++i];
    }
    installTerminateMarker();
    printf("FLOE_RESULT {\"variant\":\"%s\",\"scenario\":\"%s\",\"event\":\"start\"}\n", kVariant,
           scenario.c_str());
    fflush(stdout);
    if (scenario == "double_hullo_race")
        return scenario_double_hullo_race("double_hullo_race");
    if (scenario == "after_bye_race")
        return scenario_after_bye_race("after_bye_race");
    if (scenario == "after_bye_second_forwarder")
        return scenario_after_bye_second_forwarder("after_bye_second_forwarder");
    if (scenario == "read_race")
        return scenario_read_race("read_race");
    if (scenario == "peer_shutdown")
        return scenario_peer_shutdown("peer_shutdown");
    if (scenario == "normal_delivery")
        return scenario_normal_delivery("normal_delivery");
    if (scenario == "close_notification")
        return scenario_close_notification("close_notification");
    if (scenario == "duplicate_hullo_single_delivery")
        return scenario_duplicate_hullo_single_delivery("duplicate_hullo_single_delivery");
    if (scenario == "connect_failure")
        return scenario_connect_failure("connect_failure");
    if (scenario == "invalid_client_fd")
        return scenario_invalid_client_fd("invalid_client_fd");
    fprintf(stderr, "unknown scenario: %s\n", scenario.c_str());
    return 64;
}
